import { test, expect } from '@playwright/test';

test.describe('Table Column Sort Direction', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/table'); // Replace with the actual URL
  });

  test('should display ascending sort direction arrow when sorted ascending', async ({ page }) => {
    await page.getByRole('columnheader', { name: 'Column Name' }).click(); // Replace with actual column name
    const sortArrow = await page.getByRole('columnheader', { name: 'Column Name' }).getByText('▲'); // Replace with actual arrow indicator
    await expect(sortArrow).toBeVisible();
  });

  test('should display descending sort direction arrow when sorted descending', async ({ page }) => {
    await page.getByRole('columnheader', { name: 'Column Name' }).click(); // Replace with actual column name
    await page.getByRole('columnheader', { name: 'Column Name' }).click(); // Click again to sort descending
    const sortArrow = await page.getByRole('columnheader', { name: 'Column Name' }).getByText('▼'); // Replace with actual arrow indicator
    await expect(sortArrow).toBeVisible();
  });
});
